def decide_next_move(state):
    front_blocked, left_blocked, right_blocked = state[:3]
    goal_ahead, goal_left, goal_right = state[3:6]
    goal_direction = None

    if goal_ahead and not front_blocked:
        goal_direction = 'AHEAD'
    elif goal_left and not left_blocked:
        goal_direction = 'LEFT'
    elif goal_right and not right_blocked:
        goal_direction = 'RIGHT'

    if goal_direction is None and not (front_blocked or left_blocked or right_blocked):
        goal_direction = 'AHEAD'

    return choose_action(front_blocked, left_blocked, right_blocked, goal_direction)
